use bevy::prelude::*;
use bevy_als::als::{params::{AlsMovementParams,GroundedDynamics},state::{Gait,Stance,RotationMode},gait::calculate_gait_amount_for_thresholds,dynamics::{max_allowed_speed,simulate_grounded_velocity_with_braking_friction}};
use serde_json::{Value,json};
fn f(v:&Value)->f32{v.as_f64().unwrap()as f32}
fn vec(v:&Value)->Vec3{Vec3::from_array(std::array::from_fn(|i|f(&v[i])))}
fn dyns(v:&Value)->GroundedDynamics{GroundedDynamics{acceleration:f(&v[0]),braking_deceleration:f(&v[1]),ground_friction:f(&v[2])}}
fn main(){let input:Value=serde_json::from_str(&std::fs::read_to_string("docs/audit/bf144/441c/kernel-inputs.json").unwrap()).unwrap();let params=AlsMovementParams::default();let mut corrected=params.clone();corrected.acceleration.grounded.normal.acceleration.keys[2].leave_tangent=-3642.3720703125f32/100.;let mut rows=Vec::new();
for row in input.as_array().unwrap(){let velocity=vec(&row["relative_velocity_consumed"]);let desired=vec(&row["desired_motion"]);let thresholds=params.gait_speed_thresholds(Stance::Standing,RotationMode::ViewDirection,velocity,f(&row["view_yaw"]));let amount=calculate_gait_amount_for_thresholds(velocity.length(),thresholds);assert_eq!(amount,f(&row["gait_amount"]));let current=params.grounded_dynamics(Stance::Standing,RotationMode::ViewDirection,amount);let actual=dyns(&row["dynamics"]);assert_eq!(current,actual);let maximum=max_allowed_speed(&params,Stance::Standing,RotationMode::ViewDirection,Gait::Running,velocity,f(&row["view_yaw"]));assert_eq!(maximum,f(&row["max_speed"]));let dt=f(&row["delta"]);let braking=f(&row["braking_friction_factor"]);let run=|d|simulate_grounded_velocity_with_braking_friction(velocity,desired,maximum,d,&params.cmc,braking,dt);let(cur,steps)=run(current);assert_eq!(cur,vec(&row["planned_velocity"]),"Actual plan must match public kernel frame{}",row["ordinal"]);assert_eq!(steps,row["simulation_steps"].as_u64().unwrap()as u32);let si=dyns(&row["source_order_si"]);let cm=&row["source_curve_cm"];let native=GroundedDynamics{acceleration:f(&cm[0])/100.,braking_deceleration:f(&cm[1])/100.,ground_friction:f(&cm[2])};let data=corrected.grounded_dynamics(Stance::Standing,RotationMode::ViewDirection,amount);
rows.push(json!({"ordinal":row["ordinal"],"gait":amount,"meter_speed":velocity.length(),"current":cur.to_array(),"source_order_si":run(si).0.to_array(),"source_order_cm":run(native).0.to_array(),"raw_key_control":run(data).0.to_array(),"current_dynamics":[current.acceleration,current.braking_deceleration,current.ground_friction],"source_si_dynamics":[si.acceleration,si.braking_deceleration,si.ground_friction],"source_cm_dynamics":[native.acceleration,native.braking_deceleration,native.ground_friction]}));}
let controls=[2.125f32,2.25].map(|g|{let a=params.grounded_dynamics(Stance::Standing,RotationMode::ViewDirection,g);let b=corrected.grounded_dynamics(Stance::Standing,RotationMode::ViewDirection,g);json!({"gait":g,"current":a.acceleration,"raw_key":b.acceleration})});std::fs::write(std::env::args().nth(1).unwrap(),json!({"rows":rows,"data_controls":controls}).to_string()).unwrap();println!("Captured240 qualified actual public-kernel endpoints and curve order unit and key factors");}
